-- Add a reusable 300-word Chinese professional deck with pre-generated audio.
insert into public.template_decks (slug, name, description, level)
values (
  'xuat-nhap-khau-logistics-300-tu',
  'Xuất nhập khẩu và logistics - 300 từ',
  '300 từ vựng tiếng Trung thực tế về mua hàng, hợp đồng, Incoterms, chứng từ, hải quan, kho bãi, đóng gói, vận tải, giao nhận và xử lý sự cố. Mỗi từ có pinyin, nghĩa tiếng Việt, câu ví dụ thực tế và hai audio tạo sẵn.',
  'Logistics'
)
on conflict (slug) do update
set
  name = excluded.name,
  description = excluded.description,
  level = excluded.level;

with target_deck as (
  select id
  from public.template_decks
  where slug = 'xuat-nhap-khau-logistics-300-tu'
)
insert into public.template_cards (
  template_deck_id,
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
select
  target_deck.id,
  card.chinese,
  card.pinyin,
  card.meaning_vi,
  card.example_cn,
  card.example_pinyin,
  card.example_vi,
  card.word_audio_url,
  card.sentence_audio_url,
  card.position
from target_deck
cross join (
  values
    ('供应商资质', 'gōng yìng shāng zī zhì', 'năng lực và chứng nhận của nhà cung cấp', '我们需要审核供应商资质以确保产品质量符合要求。', 'Wǒ men xū yào shěn hé gōng yìng shāng zī zhì yǐ què bǎo chǎn pǐn zhì liàng fú hé yāo qiú.', 'Chúng tôi cần đánh giá năng lực nhà cung cấp để đảm bảo chất lượng sản phẩm đáp ứng yêu cầu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-c3d3e8b8f603038723b968de.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-2f6171dc09de30ba6310de20.mp3', 1),
    ('采购订单', 'cǎi gòu dìng dān', 'đơn đặt mua hàng hóa', '请尽快确认采购订单以便安排生产和发货。', 'Qǐng jǐn kuài quèrèn cǎi gòu dìng dān yǐ biàn ān pái shēng chǎn hé fā huò.', 'Vui lòng xác nhận đơn đặt mua càng sớm càng tốt để sắp xếp sản xuất và giao hàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-f000dd828332ba9b19ac75c4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-df3a7d228d6ad6e0b62d0c22.mp3', 2),
    ('最小订购量', 'zuì xiǎo dìng gòu liàng', 'số lượng đặt hàng tối thiểu', '供应商设定了最小订购量为一千件。', 'Gōng yìng shāng shè dìng le zuì xiǎo dìng gòu liàng wéi yī qiān jiàn.', 'Nhà cung cấp quy định số lượng đặt tối thiểu là một nghìn cái.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-a46a56504938a666d2cb34c6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-e9837cda9840c439100829c8.mp3', 3),
    ('产品规格', 'chǎn pǐn guī gé', 'quy cách, thông số kỹ thuật sản phẩm', '请提供详细的产品规格以便我们检验样品。', 'Qǐng tí gōng xiáng xì de chǎn pǐn guī gé yǐ biàn wǒ men jiǎn yàn yàng pǐn.', 'Vui lòng cung cấp quy cách chi tiết để chúng tôi kiểm tra mẫu hàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-5e4f6598716bf0e2dbfdd59d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-576deb94e8564ae1762a6e08.mp3', 4),
    ('样品申请', 'yàng pǐn shēn qǐng', 'yêu cầu lấy mẫu sản phẩm', '客户已提交样品申请，等待供应商确认。', 'Kè hù yǐ tí jiāo yàng pǐn shēn qǐng, děng dài gōng yìng shāng quèrèn.', 'Khách hàng đã gửi yêu cầu lấy mẫu, đang chờ nhà cung cấp xác nhận.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-78e3e3b94b3dcc3684eb0696.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-f6025eb54c2d24764196fca6.mp3', 5),
    ('供应能力评估', 'gōng yìng néng lì píng gū', 'đánh giá năng lực cung ứng của nhà cung cấp', '我们定期进行供应能力评估以保证交期稳定。', 'Wǒ men dìng qī jìn xíng gōng yìng néng lì píng gū yǐ bǎo zhèng jiāo qī wěn dìng.', 'Chúng tôi định kỳ đánh giá năng lực cung ứng để đảm bảo thời gian giao hàng ổn định.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-e1e3ef1f4bbecd665762f7fd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-a5bdc1547af009f072aedaeb.mp3', 6),
    ('合同确认', 'hé tóng quèrèn', 'xác nhận hợp đồng hoặc đơn hàng', '请在三天内完成合同确认并发送签字版。', 'Qǐng zài sān tiān nèi wán chéng hé tóng quèrèn bìng fā sòng qiān zì bǎn.', 'Vui lòng hoàn thành xác nhận hợp đồng trong ba ngày và gửi bản đã ký.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/word-b6339a31f420b5939c4ad389.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/xuat-nhap-khau-logistics-300-tu/sentence-aa5fac87cdd6f30c4aed7620.mp3', 7),
